-- Load production.DimMaterial (dimension, SCD type 1).
-- One stored procedure per destination table (DE Policy v2, 5.3).
-- Generated by `python -m fde render` from models/gold/production/DimMaterial.yml. Do not edit: change the spec and render again.

CREATE OR ALTER PROCEDURE [production].[LoadDimMaterial]
    @LoadDate date,
    @LoadStepID varchar(36)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now datetime2(6) = SYSUTCDATETIME();
    DECLARE @MaxKey bigint = (SELECT COALESCE(MAX([DimMaterial_SK]), 0)
                              FROM [production].[DimMaterial] WHERE [DimMaterial_SK] > 0);

    MERGE [production].[DimMaterial] AS target
    USING (
        SELECT
            CAST(s.[Material_BK] AS varchar(20)) AS [Material_BK],
            CAST(s.[MaterialName] AS varchar(150)) AS [MaterialName],
            CAST(s.[MaterialCategoryCode] AS varchar(20)) AS [MaterialCategoryCode],
            CAST(s.[MaterialSecondaryCategory] AS varchar(80)) AS [MaterialSecondaryCategory],
            CAST(s.[AggregateMaterial_BK] AS varchar(20)) AS [AggregateMaterial_BK],
            CAST(s.[AggregateMaterialName] AS varchar(80)) AS [AggregateMaterialName],
            CAST(s.[MaterialsContained] AS varchar(400)) AS [MaterialsContained],
            @MaxKey + ROW_NUMBER() OVER (ORDER BY s.[Material_BK]) AS [NewKey]
        FROM [stage].[DimMaterialSource] AS s
    ) AS source
    ON target.[Material_BK] = source.[Material_BK]
    WHEN MATCHED AND (
        (target.[MaterialName] <> source.[MaterialName] OR (target.[MaterialName] IS NULL AND source.[MaterialName] IS NOT NULL) OR (target.[MaterialName] IS NOT NULL AND source.[MaterialName] IS NULL))
        OR (target.[MaterialCategoryCode] <> source.[MaterialCategoryCode] OR (target.[MaterialCategoryCode] IS NULL AND source.[MaterialCategoryCode] IS NOT NULL) OR (target.[MaterialCategoryCode] IS NOT NULL AND source.[MaterialCategoryCode] IS NULL))
        OR (target.[MaterialSecondaryCategory] <> source.[MaterialSecondaryCategory] OR (target.[MaterialSecondaryCategory] IS NULL AND source.[MaterialSecondaryCategory] IS NOT NULL) OR (target.[MaterialSecondaryCategory] IS NOT NULL AND source.[MaterialSecondaryCategory] IS NULL))
        OR (target.[AggregateMaterial_BK] <> source.[AggregateMaterial_BK] OR (target.[AggregateMaterial_BK] IS NULL AND source.[AggregateMaterial_BK] IS NOT NULL) OR (target.[AggregateMaterial_BK] IS NOT NULL AND source.[AggregateMaterial_BK] IS NULL))
        OR (target.[AggregateMaterialName] <> source.[AggregateMaterialName] OR (target.[AggregateMaterialName] IS NULL AND source.[AggregateMaterialName] IS NOT NULL) OR (target.[AggregateMaterialName] IS NOT NULL AND source.[AggregateMaterialName] IS NULL))
        OR (target.[MaterialsContained] <> source.[MaterialsContained] OR (target.[MaterialsContained] IS NULL AND source.[MaterialsContained] IS NOT NULL) OR (target.[MaterialsContained] IS NOT NULL AND source.[MaterialsContained] IS NULL))
    ) THEN UPDATE SET
        [MaterialName] = source.[MaterialName],
        [MaterialCategoryCode] = source.[MaterialCategoryCode],
        [MaterialSecondaryCategory] = source.[MaterialSecondaryCategory],
        [AggregateMaterial_BK] = source.[AggregateMaterial_BK],
        [AggregateMaterialName] = source.[AggregateMaterialName],
        [MaterialsContained] = source.[MaterialsContained],
        [LastUpdateLoadStepID] = @LoadStepID,
        [LastUpdateTimestamp] = @Now
    WHEN NOT MATCHED BY TARGET THEN INSERT (
        [DimMaterial_SK],
        [Material_BK],
        [MaterialName],
        [MaterialCategoryCode],
        [MaterialSecondaryCategory],
        [AggregateMaterial_BK],
        [AggregateMaterialName],
        [MaterialsContained],
        [InsertLoadStepID],
        [InsertTimestamp],
        [LastUpdateLoadStepID],
        [LastUpdateTimestamp]
    ) VALUES (
        source.[NewKey],
        source.[Material_BK],
        source.[MaterialName],
        source.[MaterialCategoryCode],
        source.[MaterialSecondaryCategory],
        source.[AggregateMaterial_BK],
        source.[AggregateMaterialName],
        source.[MaterialsContained],
        @LoadStepID,
        @Now,
        @LoadStepID,
        @Now
    );
END
GO
